export const BASE            = { tag: 'v1', artifact: 'build-1', contents: ['基线'], verified: true };

export function stateAt(scenario          , index        )        {
  if (!Number.isInteger(index) || index < 0 || index >= scenario.steps.length) {
    throw new RangeError('Step outside scenario');
  }
  let state        = { main: ['基线'], develop: ['基线'], branches: [], test: '尚未部署本轮组合', candidate: null, production: BASE };
  for (const step of scenario.steps.slice(0, index + 1)) state = { ...state, ...step.patch };
  return state;
}

